stage('Install') {
    // Needed by 'gkeyll runregression': it compiles C regression tests
    // on the fly using the installed share/Makefile, and 'gkeyll' itself
    // is the interpreter runregression runs as.
    //
    // Use 'install' (from the generated alltargets.mak), not
    // 'gkeyll-install' (defined directly in the top-level Makefile):
    // the latter has two independent prerequisite chains that both
    // rebuild the same build/**/libg0*.so files, which can race under
    // -j and fail with e.g. "cp: .../libg0vlasov.so: No such file or
    // directory" when nothing has pre-built them yet.
    sh 'make -j3 install'
}

